/* Shared variables between ISR and main loop */
volatile uint32_t g_sampleReady = 0;
volatile uint32_t g_sampleValue = 0;

void PIT_IRQHandler(void) {
    /* Check if channel 0 caused the interrupt */
    if (PIT_GetStatusFlags(PIT, kPIT_Chnl_0) & kPIT_TimerFlag) {
        /* Clear the interrupt flag */
        PIT_ClearStatusFlags(PIT, kPIT_Chnl_0, kPIT_TimerFlag);

        /* Read the digital input PTC3 */
        g_sampleValue = GPIO_PinRead(GPIOC, 3U);

        /* Signal main loop that a new sample is ready */
        g_sampleReady = 1;
    }
}

int main(void) {
    /* Enable peripheral clocks for PORTC, PORTE, and PIT */
    CLOCK_EnableClock(kCLOCK_PortC);
    CLOCK_EnableClock(kCLOCK_PortE);
    CLOCK_EnableClock(kCLOCK_Pit);

    /* Configure PTC3 as digital input */
    PORT_SetPinMux(PORTC, 3U, kPORT_MuxAsGpio);
    gpio_pin_config_t input_config = {
        .pinDirection = kGPIO_DigitalInput,
        .outputLogic = 0U
    };
    GPIO_PinInit(GPIOC, 3U, &input_config);

    /* Configure PTE24 as digital output (LED) */
    PORT_SetPinMux(PORTE, 24U, kPORT_MuxAsGpio);
    gpio_pin_config_t output_config = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic = 1U
    };
    GPIO_PinInit(GPIOE, 24U, &output_config);

    /* Configure PIT */
    pit_config_t pitConfig;
    PIT_GetDefaultConfig(&pitConfig);
    PIT_Init(PIT, &pitConfig);

    /* Set timer period for 10 ms (48 MHz bus clock) */
    PIT_SetTimerPeriod(PIT, kPIT_Chnl_0, USEC_TO_COUNT(10000U, 48000000U));

    /* Enable PIT channel 0 interrupt */
    PIT_EnableInterrupts(PIT, kPIT_Chnl_0, kPIT_TimerInterruptEnable);
    EnableIRQ(PIT_IRQn);

    /* Start the PIT timer */
    PIT_StartTimer(PIT, kPIT_Chnl_0);

    while (1) {
        uint32_t ready;
        uint32_t value;
        uint32_t primask;

        /* Safely read the flag and sample value to avoid race conditions */
        primask = __get_PRIMASK();
        __disable_irq();
        ready = g_sampleReady;
        value = g_sampleValue;
        if (ready) {
            g_sampleReady = 0;
        }
        __set_PRIMASK(primask);

        /* Process the new sample if ready */
        if (ready) {
            if (value) {
                /* Toggle PTE24 (LED) if PTC3 is high */
                GPIO_PortToggle(GPIOE, 1U << 24U);
            }
        }

        /* Enter low-power state until next interrupt */
        __WFI();
    }
}

