#define BUFFER_SIZE      (512u)
#define EDMA_INSTANCE    (DMA0)
#define EDMA_CHANNEL      (0u)

/* 32-byte aligned so D-cache maintenance covers whole cache lines. */
static uint8_t s_srcBuffer[BUFFER_SIZE]  __attribute__((aligned(32)));
static uint8_t s_destBuffer[BUFFER_SIZE] __attribute__((aligned(32)));

static edma_handle_t s_edmaHandle;
static volatile bool s_transferComplete = false;

static void EDMA_UserCallback(edma_handle_t *handle,
                              void *userData,
                              bool transferDone,
                              uint32_t tcds)
{
    (void)handle;
    (void)userData;
    (void)tcds;

    if (transferDone)
    {
        s_transferComplete = true;
    }
}

/* eDMA0 channel-0 interrupt service routine. */
void DMA0_0_IRQHandler(void)
{
    EDMA_HandleIRQ(&s_edmaHandle);
    __DSB();
}

int main(void)
{
    /* --- 1. Enable the eDMA0 peripheral clock gate ------------------------- */
    CLOCK_EnableClock(kCLOCK_Dma0);

    /* --- 2. Fill the source buffer with (index & 0xFF) ------------------- */
    for (uint32_t i = 0u; i < BUFFER_SIZE; i++)
    {
        s_srcBuffer[i] = (uint8_t)(i & 0xFFu);
    }

    /* Clear destination so the verify step is meaningful. */
    for (uint32_t i = 0u; i < BUFFER_SIZE; i++)
    {
        s_destBuffer[i] = 0u;
    }

    /*
     * Keep the D-cache coherent with the eDMA engine:
     *  - push the freshly-written source data out to the bus, and
     *  - drop any stale lines the CPU may hold for the destination.
     */
    SCB_CleanDCache_by_Addr((uint32_t *)s_srcBuffer,  BUFFER_SIZE);
    SCB_CleanInvalidateDCache_by_Addr((uint32_t *)s_destBuffer, BUFFER_SIZE);

    /* --- 3. Initialise the eDMA engine and channel 0 ---------------------- */
    edma_config_t userConfig;
    EDMA_GetDefaultConfig(&userConfig);
    EDMA_Init(EDMA_INSTANCE, &userConfig);

    EDMA_CreateHandle(&s_edmaHandle, EDMA_INSTANCE, EDMA_CHANNEL);
    EDMA_SetCallback(&s_edmaHandle, EDMA_UserCallback, NULL);
    NVIC_EnableIRQ(DMA0_0_IRQn);

    edma_transfer_config_t transferConfig;
    EDMA_PrepareTransfer(&transferConfig,
                         s_srcBuffer,  1u,
                         s_destBuffer, 1u,
                         BUFFER_SIZE,  BUFFER_SIZE,
                         kEDMA_MemoryToMemory);

    EDMA_SubmitTransfer(&s_edmaHandle, &transferConfig);
    EDMA_StartTransfer(&s_edmaHandle);

    /* --- 3b. Wait for the major-loop completion callback ------------------ */
    while (!s_transferComplete)
    {
        /* busy-wait; flag is volatile */
    }

    /*
     * The DMA wrote the destination; make sure the CPU reads fresh data
     * rather than stale cache lines.
     */
    SCB_InvalidateDCache_by_Addr((uint32_t *)s_destBuffer, BUFFER_SIZE);

    /* --- 4. Verify byte-for-byte and halt on mismatch --------------------- */
    for (uint32_t i = 0u; i < BUFFER_SIZE; i++)
    {
        if (s_destBuffer[i] != (uint8_t)(i & 0xFFu))
        {
            /* Mismatch: park here forever. */
            while (1)
            {
                __BKPT(0);
            }
        }
    }

    /* Success: idle forever. */
    while (1)
    {
    }
}

