#define BUFFER_SIZE    (512U)
#define EDMA_INSTANCE  (DMA0)
#define EDMA_CHANNEL   (0U)

/* eDMA TCD CSR bit 8 = DONE — set by hardware when the major loop completes. */
#define TCD_CSR_DONE  (1U << 8U)

static uint8_t s_srcBuffer[BUFFER_SIZE]  __attribute__((aligned(32)));
static uint8_t s_destBuffer[BUFFER_SIZE] __attribute__((aligned(32)));

static edma_handle_t s_edmaHandle;

int main(void)
{
    /* 1. Fill source buffer with (index & 0xFF). */
    for (uint32_t i = 0U; i < BUFFER_SIZE; i++)
    {
        s_srcBuffer[i] = (uint8_t)(i & 0xFFU);
    }

    /* Pre-clear destination so verification is meaningful. */
    for (uint32_t i = 0U; i < BUFFER_SIZE; i++)
    {
        s_destBuffer[i] = 0U;
    }

    /*
     * Cortex-M7 D-cache coherency: eDMA accesses the bus directly,
     * bypassing the D-cache. Push source data to main memory and
     * invalidate any stale destination cache lines.
     */
    SCB_CleanDCache_by_Addr((uint32_t *)s_srcBuffer, (int32_t)BUFFER_SIZE);
    SCB_InvalidateDCache_by_Addr((uint32_t *)s_destBuffer, (int32_t)BUFFER_SIZE);

    /* 2. Initialise eDMA and create a handle for channel 0. */
    edma_config_t edmaConfig;
    EDMA_GetDefaultConfig(&edmaConfig);
    EDMA_Init(EDMA_INSTANCE, &edmaConfig);

    EDMA_CreateHandle(&s_edmaHandle, EDMA_INSTANCE, EDMA_CHANNEL);

    /* Configure the 512-byte memory-to-memory transfer. */
    edma_transfer_config_t transferConfig;
    EDMA_PrepareTransfer(&transferConfig,
                         (void *)s_srcBuffer,  1U,
                         (void *)s_destBuffer, 1U,
                         BUFFER_SIZE,           BUFFER_SIZE,
                         kEDMA_MemoryToMemory);

    if (kStatus_Success != EDMA_SubmitTransfer(&s_edmaHandle, &transferConfig))
    {
        while (1)
        {
            __BKPT(0);
        }
    }

    /* Start the transfer; EDMA_StartTransfer enables ERQ for the channel. */
    EDMA_StartTransfer(&s_edmaHandle);

    /*
     * For memory-to-memory, ensure the channel is software-triggered.
     * (EDMA_StartTransfer may already do this; the redundant trigger is harmless.)
     */
    EDMA_TriggerChannelStart(EDMA_INSTANCE, EDMA_CHANNEL);

    /* 3. Wait for the DONE bit in TCD CSR. */
    while ((EDMA_INSTANCE->TCD[EDMA_CHANNEL].CSR & TCD_CSR_DONE) == 0U)
    {
    }

    /* Invalidate destination cache so CPU reads the DMA-written data. */
    SCB_InvalidateDCache_by_Addr((uint32_t *)s_destBuffer, (int32_t)BUFFER_SIZE);

    /* 4. Verify byte-for-byte; halt in an infinite loop on mismatch. */
    for (uint32_t i = 0U; i < BUFFER_SIZE; i++)
    {
        if (s_destBuffer[i] != (uint8_t)(i & 0xFFU))
        {
            while (1)
            {
                __BKPT(0);
            }
        }
    }

    /* Success: idle forever. */
    while (1)
    {
    }
}

